import{z as l,x as i,o as a,c as d,q as t,j as A,D as e,d as o,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"能耗预算","description":"","frontmatter":{"title":"能耗预算","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/edge-energy-budget.md","filePath":"llm/edge-energy-budget.md","lastUpdated":1791063341000}'),s={name:"llm/edge-energy-budget.md"};function m(p,E,D,h,_,C){const B=i("Mermaid");return a(),d("div",null,[E[2]||(E[2]=t('<h1 id="能耗预算" tabindex="-1">能耗预算 <a class="header-anchor" href="#能耗预算" aria-label="Permalink to &quot;能耗预算&quot;">​</a></h1><div class="epigraph"><p>端侧性能的上限不是峰值算力，是散热能持续带走的那点热：首 token 快，不等于第二十秒还快。</p><footer>—— 据 Horowitz, Computing&#39;s Energy Problem, ISSCC 2014 的能耗口径整理</footer></div><p><a href="/llm/edge-memory-management">上一课</a>把内存按峰值管起来；另一份按持续时间管的账是能耗与热。移动 SoC 的持续功率只有峰值的一个零头，降频一来带宽与算力同时缩水，前几课算的时间下界全部要重算。本课写能耗账怎么记、热节流怎么改写性能、以及「限速反而更快跑完」的工程含义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>能耗账的最小单元是每 token 能耗：\\(E = P \\cdot t_{\\mathrm{decode}}\\)。decode 被字节搬运钉死，所以能耗大头不是乘加，是每 token 把几个 GB 的权重从 DRAM 读一遍——<a href="/llm/arithmetic-intensity-decode">解码的算术强度</a>的同一结论在能耗上重演。Horowitz 的经典口径把片外 DRAM 访问的能耗放在片上 SRAM 约两个数量级之上：搬运即能耗，量化省字节同时就是省电。热的约束更直接：SoC 峰值功率能到十瓦级，皮肤温度允许的持续功率只有一两瓦，超了就降频。于是短跑与长跑差出数倍：冷启动跑分漂亮，两分钟后降频把速率砍半，用户说的「越用越卡」一半是它。<span class="marginnote">把 \\(E = P \\cdot t_{\\mathrm{decode}}\\) 代入具体数：解码稳定在 2 瓦、生成一千个 token 花了 50 秒，这次能耗就是 2 W × 50 s = 100 焦耳，约合 28 毫瓦时——按一块 4000 mAh 手机电池约 15 瓦时计，占千分之二不到。单次不起眼，但连续对话一小时就是肉眼可见的掉电，这就是要用「毫瓦时每千 token」记账的原因。</span></p><h3 id="记账单位" tabindex="-1">记账单位 <a class="header-anchor" href="#记账单位" aria-label="Permalink to &quot;记账单位&quot;">​</a></h3><p>记账单位建议用毫瓦时每千 token，而不是 token 每秒：前者能跨设备比续航、能折算成「一次对话耗掉电池的百分比」，后者只是峰值速度，还随温度漂。测量分两级：软件侧用系统耗电归因（Android 的 perfetto 与 Battery Historian、iOS 的能耗日志）定位到进程；标定与验收用外接功率计——软件归因的绝对值不可信，趋势可用。</p>',7)),(a(),A(n,null,{default:e(()=>[r(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20F%5B%22%E5%85%A8%E9%80%9F%E8%BF%90%E8%A1%8C%3A%20%E5%8A%9F%E7%8E%87%E4%B8%8A%E5%86%B2%22%5D%0A%20%20F%20--%3E%20T%7B%22%E7%BB%93%E6%B8%A9%E8%B6%85%E9%98%88%3F%22%7D%0A%20%20T%20--%3E%7C%E6%98%AF%7C%20D%5B%22DVFS%20%E9%99%8D%E9%A2%91%3A%20%E5%B8%A6%E5%AE%BD%E7%AE%97%E5%8A%9B%E5%90%8C%E9%99%8D%22%5D%0A%20%20D%20--%3E%20S%5B%22decode%20%E5%8F%98%E6%85%A2%E4%B8%94%E8%83%BD%E6%95%88%E5%8F%98%E5%B7%AE%22%5D%0A%20%20S%20--%3E%20T2%7B%22%E8%B4%9F%E8%BD%BD%E6%8C%81%E7%BB%AD%3F%22%7D%0A%20%20T2%20--%3E%7C%E6%98%AF%7C%20L%5B%22%E7%A8%B3%E5%AE%9A%E5%9C%A8%E5%8F%AF%E6%8C%81%E7%BB%AD%E5%8A%9F%E7%8E%87%22%5D%0A%20%20T2%20--%3E%7C%E5%90%A6%7C%20C%5B%22%E5%9B%9E%E6%B8%A9%E5%9B%9E%E8%90%BD%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>策略按收益排。第一是量化：少读字节直接省电，上一课的 4-bit 在能耗账上再赚一次。第二是热点放 NPU：能效高的执行单元做同样的搬运与计算花更少的焦耳，但必须以实测的毫瓦时每千 token 验收，不认 TOPS/W 宣传值。第三是限速：把生成速率钉在可持续功率对应的速率上，避免「全速—节流—全速」的振荡。第四是调度：prefill 批着做，UI 把非急迫的计算挪到充电或低温场景。每条策略都要能回答「省的是哪一项」：字节、焦耳，还是峰值功率。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>「限速反而更快」的机理在能效曲线：DVFS 的能效最优点不在最高频，电压随频率超线性上涨，同样的计算在高频下花更多焦耳。全速运行先撞温度墙，再被系统压到比主动限速更低的速率，期间多烧的电全变成了热。把速率钉在稳态点，总时间更短、总能耗更低、机身不烫。运行时的监控回路因此长成：以结温或功率为信号，调节生成速率与上下文长度，把稳态速率当运行参数而不是宣传数字。</p><p><span class="marginnote">同一台设备夏季空调房与冬季口袋里、金属壳与塑料壳下，持续功率能差三成：稳态速率不是常量，要按温度带标定，或让运行时用温度反馈自调。</span></p><p>同一段长生成任务，「全速」与「限速」两条策略走出来的路径：</p>',6)),(a(),A(n,null,{default:e(()=>[r(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20TASK%5B%22%E4%B8%80%E6%AE%B5%E9%95%BF%E7%94%9F%E6%88%90%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20A%5B%22%E5%85%A8%E9%80%9F%E7%AD%96%E7%95%A5%22%5D%0A%20%20TASK%20--%3E%20B%5B%22%E9%99%90%E9%80%9F%E7%AD%96%E7%95%A5%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E5%87%A0%E5%8D%81%E7%A7%92%E5%90%8E%E6%92%9E%E6%B8%A9%E5%BA%A6%E5%A2%99%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E7%B3%BB%E7%BB%9F%E5%8E%8B%E9%A2%91%EF%BC%9A%E6%AF%94%E4%B8%BB%E5%8A%A8%E9%99%90%E9%80%9F%E6%9B%B4%E4%BD%8E%22%5D%0A%20%20A2%20--%3E%20A3%5B%22%E5%A4%9A%E7%83%A7%E7%9A%84%E7%94%B5%E5%85%A8%E5%8F%98%E6%88%90%E7%83%AD%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E9%80%9F%E7%8E%87%E9%92%89%E5%9C%A8%E5%8F%AF%E6%8C%81%E7%BB%AD%E5%8A%9F%E7%8E%87%E7%82%B9%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E5%85%A8%E7%A8%8B%E4%B8%8D%E8%A7%A6%E5%8F%91%E8%8A%82%E6%B5%81%22%5D%0A%20%20A3%20--%3E%20OUT%5B%22%E6%80%BB%E6%97%B6%E9%97%B4%E6%9B%B4%E9%95%BF%EF%BC%8C%E6%80%BB%E8%83%BD%E8%80%97%E6%9B%B4%E9%AB%98%22%5D%0A%20%20B2%20--%3E%20WIN%5B%22%E6%80%BB%E6%97%B6%E9%97%B4%E6%9B%B4%E7%9F%AD%EF%BC%8C%E6%9C%BA%E8%BA%AB%E4%B8%8D%E7%83%AB%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p><span class="marginnote">DVFS（动态电压频率调节）是 SoC 的自动油门：温度高或负载变化时降频率、降电压来省电降温。关键在电压随频率超线性上涨——频率提 20%，电压可能要提 30%，而功率大致按电压平方涨，于是同样的计算放到高频下更费电。这就是「能效最优点不在最高频率」的来源，也是限速能又快又省的物理根据。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写电池化学与充电策略。不同 SoC 的能效曲线差异大，任何数字都要在目标设备实测；外接功率计是标定源，软件归因只做定位。NPU 的能效优势在稀疏、低精度峰值下宣传值虚高，一律按实测焦耳每 token 记账。<span class="marginnote">初学者容易被「NPU 算力 xx TOPS」的宣传数字说服。TOPS 是峰值算力，实际推理受内存带宽和散热双重限制，真实能效要看实测的毫瓦时每千 token——就像买汽车看等速油耗比看最大马力更贴近日常体验。验收时用外接功率计实测，不认 datasheet 上的 TOPS/W。</span>车载与可穿戴的散热形态不同，方法同构但预算另列。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>能耗账的最小单元是焦耳每 token，大头是 DRAM 搬运；量化省字节即省电。</li><li>热节流让持续性能远低于峰值，长跑与跑分差数倍是常态而非异常。</li><li>记账用毫瓦时每千 token；软件归因定位、功率计标定。</li><li>限速运行在能效稳态点，比全速—节流振荡更快、更省、不烫手。</li><li>出处：Horowitz, Computing&#39;s Energy Problem, ISSCC 2014 的能耗口径；系统级耗电归因工具文档；按本课程实测方法整理。</li></ul>',5))])}const S=l(s,[["render",m]]);export{F as __pageData,S as default};
